function gtag(){dataLayer.push(arguments);}
gtag("js", new Date());
gtag("config", "G-JGGDQ7PN0E");

body.script:
        const STORAGE_KEY = 'enfoque_mundial_news';
        const urlParams = new URLSearchParams(window.location.search);
        const newsId = parseInt(urlParams.get('id'));

        function loadArticle() {
            let allNews = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
            const news = allNews.find(n => n.id === newsId);

            if (!news) {
                document.getElementById('article-content').innerHTML = "
Noticia no encontrada";
                return;
            }

            // Incrementar vistas
            news.views = (news.views || 0) + 1;
            localStorage.setItem(STORAGE_KEY, JSON.stringify(allNews));

            const container = document.getElementById('article-content');
            container.innerHTML = `


                    ${news.category}

${news.title}







${news.author}

${new Date(news.date).toLocaleString('es-ES', { dateStyle: 'long', timeStyle: 'short' })}







                    ${news.images.map(img => `




                    `).join('')}




                    ${news.content}

            `;
            lucide.createIcons();
        }

        function share() {
            if (navigator.share) {
                navigator.share({ title: document.title, url: window.location.href });
            }
        }

        window.onload = loadArticle;
